class Solution {
public:
    string frequencySort(string s) {
        map<char, int> cnt;
        for (char c : s) cnt[c]++;
        priority_queue<pair<int, char>> pq;
        for (auto& [c, f] : cnt) pq.push({f, c});
        string res;
        while (!pq.empty()) {
            auto [f, c] = pq.top();
            pq.pop();
            res += string(f, c);
        }
        return res;
    }
};
